	s.delivs[id] = copyDelivery(d)
	return copyDelivery(d), nil
}

func copyDelivery(d Delivery) Delivery {
	for _, p := range []**time.Time{&d.NextAttemptAt, &d.LastAttemptAt} {
		if *p != nil {
			t := **p
			*p = &t
		}
	}
	return d
